import sys, math, itertools, random, bisect, heapq
from functools import lru_cache
from collections import Counter, defaultdict, deque
from pathlib import Path

def fibonacci(text):
    if hasattr(sys, 'set_int_max_str_digits'):
        sys.set_int_max_str_digits(0)
    n = int(text)
    (a, b) = (0, 1)
    for bit in bin(n)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        if bit == '0':
            (a, b) = (c, d)
        else:
            (a, b) = (d, c + d)
    return str(a)
import sys
sys.stdout.write(fibonacci(sys.stdin.read()) + '\n')
